{"path": "/app/ars.R", "content": "# Adaptive rejection sampling (ARS)
#
# A dependency-free implementation of Gilks and Wild (1992).  The target is
# one-dimensional and log-concave on the supplied interval.  Tangents to its
# log density form a piecewise-exponential rejection envelope; rejected points
# are inserted into the envelope.

.ars_make_density <- function(density, log = FALSE, envir = parent.frame()) {
  if (is.function(density)) {
    f <- density
  } else if (inherits(density, "formula")) {
    if (length(density) != 2L) stop("density formula must be one-sided, e.g. ~ exp(-x^2/2)")
    expr <- density[[2L]]
    f <- function(x) eval(expr, envir = list(x = x), enclos = envir)
  } else if (is.expression(density) || is.language(density)) {
    expr <- if (is.expression(density)) density[[1L]] else density
    f <- function(x) eval(expr, envir = list(x = x), enclos = envir)
  } else if (is.character(density) && length(density) == 1L) {
    # A function name (such as "dnorm") is accepted; otherwise parse an x-expression.
    named <- tryCatch(get(density, mode = "function", envir = envir), error = function(e) NULL)
    if (!is.null(named)) f <- named else {
      expr <- parse(text = density)[[1L]]
      f <- function(x) eval(expr, envir = list(x = x), enclos = envir)
    }
  } else stop("density must be a function, expression, one-sided formula, or function name")

  function(x) {
    y <- tryCatch(f(x), error = function(e) stop("density evaluation failed: ", conditionMessage(e)))
    if (!is.numeric(y) || length(y) != length(x))
      stop("density must return one numeric value per input (it must be vectorized)")
    if (any(is.na(y) | is.nan(y))) stop("density returned NA or NaN")
    if (log) {
      if (any(y == Inf)) stop("log density returned +Inf")
      as.numeric(y)
    } else {
      if (any(!is.finite(y)) || any(y < 0)) stop("density must return finite, non-negative values")
      log(as.numeric(y))
    }
  }
}

.ars_derivative <- function(x, logf, domain) {
  # Symmetric differences where possible, one-sided differences near endpoints.
  eps <- (.Machine$double.eps)^(1/3) * (1 + abs(x))
  left <- pmax(x - eps, domain[1L])
  right <- pmin(x + eps, domain[2L])
  out <- numeric(length(x))
  for (i in seq_along(x)) {
    vals <- logf(c(left[i], right[i]))
    if (!all(is.finite(vals)) || right[i] <= left[i])
      stop("cannot numerically differentiate log density; use interior initial points or dlog_density")
    out[i] <- (vals[2L] - vals[1L]) / (right[i] - left[i])
  }
  out
}

.ars_initial_points <- function(domain) {
  lo <- domain[1L]; hi <- domain[2L]
  if (is.finite(lo) && is.finite(hi)) lo + c(.2, .5, .8) * (hi - lo)
  else if (is.finite(lo)) lo + c(.5, 1, 2)
  else if (is.finite(hi)) hi - c(2, 1, .5)
  else c(-1, 0, 1)
}

.ars_check_concavity <- function(x, h, hp, tol = 1e-7) {
  o <- order(x); x <- x[o]; h <- h[o]; hp <- hp[o]
  scale <- 1 + max(abs(hp))
  if (length(x) > 1L && any(diff(hp) > tol * scale))
    stop("target is not log-concave: log-density derivatives increase")
  # Secant slopes must lie between adjacent derivatives for a concave function.
  if (length(x) > 1L) {
    sec <- diff(h) / diff(x)
    if (any(sec > hp[-length(hp)] + tol * scale) ||
        any(sec < hp[-1L] - tol * scale))
      stop("target is not log-concave: secant/tangent check failed")
  }
  invisible(TRUE)
}

.ars_build_hull <- function(x, h, hp, domain, tol = 1e-7) {
  o <- order(x); x <- x[o]; h <- h[o]; hp <- hp[o]
  .ars_check_concavity(x, h, hp, tol)

  # On exactly log-linear regions all tangent lines coincide.  Retaining one
  # avoids division by zero and is mathematically equivalent.
  if (length(x) > 1L) {
    keep <- rep(TRUE, length(x))
    last <- 1L
    for (i in 2:length(x)) {
      slope_close <- abs(hp[i] - hp[last]) <= tol * (1 + max(abs(hp[c(i, last)])))
      intercept_close <- abs((h[i] - hp[i] * x[i]) - (h[last] - hp[last] * x[last])) <=
        20 * tol * (1 + abs(h[i]) + abs(h[last]))
      if (slope_close && intercept_close) keep[i] <- FALSE else last <- i
    }
    x <- x[keep]; h <- h[keep]; hp <- hp[keep]
  }

  k <- length(x)
  z <- c(domain[1L], if (k > 1L) {
    (h[2:k] - h[1:(k-1L)] - x[2:k] * hp[2:k] + x[1:(k-1L)] * hp[1:(k-1L)]) /
      (hp[1:(k-1L)] - hp[2:k])
  }, domain[2L])
  if (any(is.na(z)) || any(diff(z) <= 0) ||
      (k > 1L && any(z[2:k] < x[1:(k-1L)] - tol | z[2:k] > x[2:k] + tol)))
    stop("target is not log-concave: invalid tangent intersections")
  if (!is.finite(domain[1L]) && hp[1L] <= 0)
    stop("initial points do not produce an integrable left tail; provide wider initial points")
  if (!is.finite(domain[2L]) && hp[k] >= 0)
    stop("initial points do not produce an integrable right tail; provide wider initial points")

  list(x = x, h = h, hp = hp, z = z,
       intercept = h - hp * x)
}

.ars_log_integrals <- function(hull) {
  k <- length(hull$x); ans <- numeric(k)
  for (i in seq_len(k)) {
    l <- hull$z[i]; r <- hull$z[i + 1L]
    b <- hull$hp[i]; a <- hull$intercept[i]
    if (abs(b) < 1e-12) {
      if (!is.finite(l) || !is.finite(r)) stop("non-integrable flat envelope tail")
      ans[i] <- a + log(r - l)
    } else if (b > 0) {
      if (!is.finite(r)) stop("non-integrable right envelope tail")
      q <- if (is.finite(l)) exp(b * (l - r)) else 0
      ans[i] <- a + b * r + log1p(-q) - log(b)
    } else {
      if (!is.finite(l)) stop("non-integrable left envelope tail")
      q <- if (is.finite(r)) exp(b * (r - l)) else 0
      ans[i] <- a + b * l + log1p(-q) - log(-b)
    }
  }
  ans
}

.ars_draw_envelope <- function(hull) {
  lm <- .ars_log_integrals(hull)
  w <- exp(lm - max(lm)); w <- w / sum(w)
  piece <- sample.int(length(w), 1L, prob = w)
  l <- hull$z[piece]; r <- hull$z[piece + 1L]; b <- hull$hp[piece]
  u <- runif(1L)
  if (abs(b) < 1e-12) {
    value <- l + u * (r - l)
  } else if (b > 0) {
    q <- if (is.finite(l)) exp(b * (l - r)) else 0
    value <- r + log(q + u * (1 - q)) / b
  } else {
    q <- if (is.finite(r)) exp(b * (r - l)) else 0
    value <- l + log1p(-u * (1 - q)) / b
  }
  list(value = value, piece = piece,
       upper = hull$intercept[piece] + b * value)
}

.ars_lower_hull <- function(y, x, h) {
  # Chords give a squeezing function only between support points.
  j <- findInterval(y, x)
  if (j < 1L || j >= length(x)) return(-Inf)
  h[j] + (y - x[j]) * (h[j + 1L] - h[j]) / (x[j + 1L] - x[j])
}

#' Draw samples by adaptive rejection sampling
#'
#' @param n non-negative integer number of draws.
#' @param density vectorized (possibly unnormalised) density function. An
#'   expression involving x, a one-sided formula, or function name also works.
#' @param domain length-two support interval; infinite endpoints are allowed.
#' @param initial interior support points. Defaults suit common centred targets.
#' @param log whether density returns log density rather than density.
#' @param dlog_density optional vectorized derivative of log density.
#' @param max_iterations safety limit on all envelope proposals.
#' @param max_points maximum number of adaptive support points.
#' @param concavity_tol numerical tolerance used in concavity checks.
ars <- function(n, density, domain = c(-Inf, Inf), initial = NULL,
                log = FALSE, dlog_density = NULL,
                max_iterations = max(10000L, 1000L * n), max_points = 1000L,
                concavity_tol = 1e-7) {
  if (!is.numeric(n) || length(n) != 1L || !is.finite(n) || n < 0 || n != floor(n))
    stop("n must be one non-negative integer")
  n <- as.integer(n)
  if (!is.numeric(domain) || length(domain) != 2L || any(is.na(domain)) ||
      domain[1L] >= domain[2L] || domain[1L] == Inf || domain[2L] == -Inf)
    stop("domain must be an increasing numeric pair, e.g. c(-Inf, Inf)")
  if (!is.logical(log) || length(log) != 1L || is.na(log)) stop("log must be TRUE or FALSE")
  if (!is.numeric(max_iterations) || length(max_iterations) != 1L ||
      !is.finite(max_iterations) || max_iterations < 1) stop("max_iterations must be positive")
  if (!is.numeric(max_points) || length(max_points) != 1L || max_points < 1)
    stop("max_points must be positive")
  if (!is.numeric(concavity_tol) || length(concavity_tol) != 1L ||
      !is.finite(concavity_tol) || concavity_tol <= 0) stop("concavity_tol must be positive")

  logf <- .ars_make_density(density, log, parent.frame())
  if (is.null(initial)) initial <- .ars_initial_points(domain)
  if (!is.numeric(initial) || length(initial) < 1L || any(!is.finite(initial)) ||
      any(initial <= domain[1L] | initial >= domain[2L]) || anyDuplicated(initial))
    stop("initial must contain distinct, finite points strictly inside domain")
  x <- sort(as.numeric(initial)); h <- logf(x)
  if (any(!is.finite(h))) stop("density must be positive and finite at every initial point")

  if (is.null(dlog_density)) {
    deriv <- function(q) .ars_derivative(q, logf, domain)
  } else {
    if (!is.function(dlog_density)) stop("dlog_density must be a function")
    deriv <- function(q) {
      v <- dlog_density(q)
      if (!is.numeric(v) || length(v) != length(q) || any(!is.finite(v)))
        stop("dlog_density must return one finite numeric value per input")
      as.numeric(v)
    }
  }
  hp <- deriv(x)
  .ars_check_concavity(x, h, hp, concavity_tol)
  hull <- .ars_build_hull(x, h, hp, domain, concavity_tol)
  # Calling ars(0, ...) still validates all inputs and the initial hull.
  if (n == 0L) return(numeric())

  answer <- numeric(n); accepted <- 0L; iterations <- 0L
  while (accepted < n) {
    iterations <- iterations + 1L
    if (iterations > max_iterations) stop("maximum iterations exceeded; target/domain may be unsuitable")
    hull <- .ars_build_hull(x, h, hp, domain, concavity_tol)
    proposal <- .ars_draw_envelope(hull)
    y <- proposal$value; upper <- proposal$upper
    logu <- log(runif(1L))
    lower <- .ars_lower_hull(y, x, h)

    accept <- logu <= lower - upper
    hy <- NA_real_
    if (!accept) {
      hy <- logf(y)
      # A tangent must dominate the true log density. This runtime test catches
      # non-concavity even when it was absent from the initial support points.
      if (is.finite(hy) && hy > upper + concavity_tol * (1 + abs(hy)))
        stop("target is not log-concave: density rose above its tangent envelope")
      accept <- is.finite(hy) && logu <= hy - upper
    }
    if (accept) {
      accepted <- accepted + 1L
      answer[accepted] <- y
    }

    # Add every evaluated, finite point, whether accepted or rejected.
    if (!is.na(hy) && is.finite(hy) && length(x) < max_points &&
        all(abs(x - y) > sqrt(.Machine$double.eps) * (1 + abs(y)))) {
      pos <- findInterval(y, x) + 1L
      dh <- deriv(y)
      x <- append(x, y, after = pos - 1L)
      h <- append(h, hy, after = pos - 1L)
      hp <- append(hp, dh, after = pos - 1L)
      .ars_check_concavity(x, h, hp, concavity_tol)
    }
  }
  attr(answer, "proposals") <- iterations
  attr(answer, "acceptance_rate") <- n / iterations
  answer
}

# Formal, reproducible tests against known normal and exponential truth.
# Returns invisibly TRUE only when every test passes.
test <- function() {
  results <- logical()
  report <- function(name, ok, values = numeric()) {
    m <- if (length(values)) mean(values) else NA_real_
    s <- if (length(values) > 1L) sd(values) else NA_real_
    cat(sprintf("%s: %s (mean=%s, sd=%s)\n", name, if (ok) "PASS" else "FAIL",
                ifelse(is.na(m), "NA", sprintf("%.5f", m)),
                ifelse(is.na(s), "NA", sprintf("%.5f", s))))
    results[name] <<- isTRUE(ok)
  }

  set.seed(1992)
  normal <- tryCatch(ars(4000, dnorm, dlog_density = function(x) -x), error = identity)
  normal_ok <- is.numeric(normal) && length(normal) == 4000L &&
    abs(mean(normal)) < 0.06 && abs(sd(normal) - 1) < 0.06
  report("NORMAL_DISTRIBUTION", normal_ok, if (is.numeric(normal)) normal else numeric())
  if (is.numeric(normal)) write.table(normal, file = "/app/normal_samples.txt",
                                      row.names = FALSE, col.names = FALSE)

  set.seed(1993)
  expo <- tryCatch(ars(4000, dexp, domain = c(0, Inf),
                       dlog_density = function(x) rep(-1, length(x))), error = identity)
  expo_ok <- is.numeric(expo) && length(expo) == 4000L && all(expo >= 0) &&
    abs(mean(expo) - 1) < 0.08 && abs(sd(expo) - 1) < 0.08
  report("EXPONENTIAL_DISTRIBUTION", expo_ok, if (is.numeric(expo)) expo else numeric())

  # Deterministic module test: normal tangent intersections and envelope values.
  module_ok <- tryCatch({
    xx <- c(-1, 0, 1); hh <- dnorm(xx, log = TRUE); hp0 <- -xx
    hu <- .ars_build_hull(xx, hh, hp0, c(-Inf, Inf))
    max(abs(hu$z[2:3] - c(-.5, .5))) < 1e-10 &&
      all(.ars_log_integrals(hu) < Inf)
  }, error = function(e) FALSE)
  report("HULL_MODULE", module_ok, c(-.5, .5))

  invalid_ok <- inherits(try(ars(-1, dnorm), silent = TRUE), "try-error") &&
    inherits(try(ars(2, dnorm, domain = c(1, -1)), silent = TRUE), "try-error")
  report("INPUT_VALIDATION", invalid_ok)

  # Student t is not globally log-concave; these points expose increasing tail slopes.
  nonconcave_ok <- inherits(try(ars(10, dt, initial = c(-3, -1, 0, 1, 3)), silent = TRUE),
                            "try-error")
  report("NON_LOG_CONCAVE_REJECTION", nonconcave_ok)

  all_ok <- all(results)
  cat(sprintf("OVERALL: %s (mean=%d, sd=%.5f)\n", if (all_ok) "PASS" else "FAIL",
              sum(results), sd(as.numeric(results))))
  invisible(all_ok)
}
"}

