{"path": "/app/solution.sh", "content": "#!/usr/bin/env bash
set -euo pipefail

ROOT=/app
DATA_DIR="$ROOT/data"
MAG_CSV="$DATA_DIR/mag.csv"
PEAKS_CSV="$DATA_DIR/peaks.csv"

mkdir -p "$DATA_DIR"

if [[ "${PEAKS_ONLY:-0}" != "1" ]]; then
    python3 "$ROOT/audioproc.py"
fi

# Keep the three greatest magnitudes in each frame. On an exact magnitude tie,
# rank the lower bin first so output is deterministic. mag.csv is frame-major,
# as emitted by audioproc.py.
awk -F, '
BEGIN {
    OFS = ","
    print "frame", "f1_bin", "f2_bin", "f3_bin"
}
NR == 1 { next }
function better(v, b, oldv, oldb) {
    return (v > oldv || (v == oldv && b < oldb))
}
function emit() {
    if (have_frame)
        print current_frame, top_bin[1], top_bin[2], top_bin[3]
}
{
    frame = $1 + 0
    bin = $2 + 0
    val = $3 + 0

    if (!have_frame || frame != current_frame) {
        emit()
        delete top_val
        delete top_bin
        top_val[1] = top_val[2] = top_val[3] = -1
        top_bin[1] = top_bin[2] = top_bin[3] = -1
        current_frame = frame
        have_frame = 1
    }

    if (better(val, bin, top_val[1], top_bin[1])) {
        top_val[3] = top_val[2]; top_bin[3] = top_bin[2]
        top_val[2] = top_val[1]; top_bin[2] = top_bin[1]
        top_val[1] = val;        top_bin[1] = bin
    } else if (better(val, bin, top_val[2], top_bin[2])) {
        top_val[3] = top_val[2]; top_bin[3] = top_bin[2]
        top_val[2] = val;        top_bin[2] = bin
    } else if (better(val, bin, top_val[3], top_bin[3])) {
        top_val[3] = val;        top_bin[3] = bin
    }
}
END { emit() }
' "$MAG_CSV" > "$PEAKS_CSV"
"}

