{"path": "/app/solution_chem_agent.py", "content": "#!/usr/bin/env python3
"""Local molecular-property search using RDKit.

The molecule catalogue is read exclusively from
``/app/resources/test_molecules.json``.  Properties included in that file are
returned by :func:`get_molecules_by_name`; property searches deliberately
recalculate them from SMILES with RDKit.
"""

from __future__ import annotations

import argparse
import json
import math
from pathlib import Path
from typing import Any

from rdkit import Chem
from rdkit.Chem import Crippen, Descriptors, Lipinski, rdMolDescriptors


DATA_FILE = Path("/app/resources/test_molecules.json")
SUPPORTED_PROPERTIES = {
    "logp",
    "mw",
    "donors",
    "acceptors",
    "rotatable_bonds",
    "tpsa",
}


def _load_molecules() -> list[dict[str, Any]]:
    """Read and minimally validate the local molecule catalogue."""
    try:
        with DATA_FILE.open("r", encoding="utf-8") as handle:
            data = json.load(handle)
    except FileNotFoundError as exc:
        raise FileNotFoundError(f"Molecule data file not found: {DATA_FILE}") from exc
    except json.JSONDecodeError as exc:
        raise ValueError(f"Invalid JSON in molecule data file: {exc}") from exc
    except OSError as exc:
        raise OSError(f"Could not read molecule data file {DATA_FILE}: {exc}") from exc

    molecules = data.get("molecules") if isinstance(data, dict) else None
    if not isinstance(molecules, list):
        raise ValueError("Molecule data must contain a top-level 'molecules' list")
    return molecules


def get_molecules_by_name(query: str, limit: int = 5) -> list:
    """Return catalogue entries whose names contain *query*.

    Matching is case-insensitive and treats ``query`` as literal text, not a
    regular expression.  An empty query matches every named molecule.  Each
    returned dictionary contains only ``name``, ``smiles``, and ``properties``
    so callers receive the requested stable interface rather than catalogue
    metadata such as CIDs.
    """
    if not isinstance(query, str):
        raise TypeError("query must be a string")
    if isinstance(limit, bool) or not isinstance(limit, int):
        raise TypeError("limit must be an integer")
    if limit < 0:
        raise ValueError("limit must be non-negative")
    if limit == 0:
        return []

    needle = query.casefold()
    results: list[dict[str, Any]] = []
    for entry in _load_molecules():
        if not isinstance(entry, dict):
            continue
        name = entry.get("name")
        smiles = entry.get("smiles")
        if not isinstance(name, str) or not isinstance(smiles, str):
            continue
        if needle in name.casefold():
            properties = entry.get("properties", {})
            results.append(
                {
                    "name": name,
                    "smiles": smiles,
                    "properties": dict(properties)
                    if isinstance(properties, dict)
                    else {},
                }
            )
            if len(results) >= limit:
                break
    return results


def smiles_to_mol(smiles: str) -> object:
    """Convert a SMILES string to an RDKit molecule, or return ``None``.

    RDKit can raise for a few malformed input types/strings; this function
    intentionally converts all invalid SMILES cases into the documented
    ``None`` result.
    """
    if not isinstance(smiles, str) or not smiles.strip():
        return None
    try:
        return Chem.MolFromSmiles(smiles)
    except (TypeError, ValueError, RuntimeError):
        return None


def compute_properties(mol: object) -> dict:
    """Calculate the required molecular descriptors with RDKit.

    Integer-valued counts are explicitly cast to ``int`` and continuous
    descriptors to ``float`` to make the returned schema predictable.
    """
    if mol is None:
        raise ValueError("mol must be a valid RDKit molecule")
    try:
        return {
            "logp": float(Crippen.MolLogP(mol)),
            "mw": float(Descriptors.MolWt(mol)),
            "donors": int(Lipinski.NumHDonors(mol)),
            "acceptors": int(Lipinski.NumHAcceptors(mol)),
            "rotatable_bonds": int(Lipinski.NumRotatableBonds(mol)),
            "tpsa": float(rdMolDescriptors.CalcTPSA(mol)),
        }
    except (TypeError, ValueError, RuntimeError, AttributeError) as exc:
        raise ValueError("mol must be a valid RDKit molecule") from exc


def _finite_number(value: Any, label: str) -> float:
    """Validate and normalize a finite real-valued argument."""
    if isinstance(value, bool):
        raise TypeError(f"{label} must be a number")
    try:
        result = float(value)
    except (TypeError, ValueError) as exc:
        raise TypeError(f"{label} must be a number") from exc
    if not math.isfinite(result):
        raise ValueError(f"{label} must be finite")
    return result


def find_candidates_for_property(
    property_name: str,
    target_value: float,
    query: str,
    tolerance: float = 0.5,
    limit: int = 10,
) -> list:
    """Find name-matched molecules close to a target RDKit property value.

    ``match_quality`` is the absolute difference from the target, so zero is
    an exact match and lower values are better.  The tolerance is inclusive.
    Invalid SMILES records are skipped rather than aborting the whole search.
    """
    if not isinstance(property_name, str):
        raise TypeError("property_name must be a string")
    canonical_property = property_name.strip().casefold()
    if canonical_property not in SUPPORTED_PROPERTIES:
        supported = ", ".join(sorted(SUPPORTED_PROPERTIES))
        raise ValueError(
            f"Unsupported property {property_name!r}; choose one of: {supported}"
        )
    if not isinstance(query, str):
        raise TypeError("query must be a string")
    if isinstance(limit, bool) or not isinstance(limit, int):
        raise TypeError("limit must be an integer")
    if limit < 0:
        raise ValueError("limit must be non-negative")
    if limit == 0:
        return []

    target = _finite_number(target_value, "target_value")
    allowed_difference = _finite_number(tolerance, "tolerance")
    if allowed_difference < 0:
        raise ValueError("tolerance must be non-negative")

    # Fetch the whole set of name matches before applying the result limit;
    # otherwise early non-matches could hide valid later catalogue entries.
    catalogue_size = len(_load_molecules())
    molecules = get_molecules_by_name(query, limit=catalogue_size)

    candidates: list[dict[str, Any]] = []
    for molecule in molecules:
        mol = smiles_to_mol(molecule["smiles"])
        if mol is None:
            continue
        properties = compute_properties(mol)
        actual = float(properties[canonical_property])
        difference = float(abs(actual - target))
        if difference <= allowed_difference:
            candidate: dict[str, Any] = {
                "name": molecule["name"],
                "smiles": molecule["smiles"],
                **properties,
                "match_quality": difference,
                "target_property": canonical_property,
                "actual_value": actual,
                "target_value": target,
            }
            candidates.append(candidate)

    # Name is a deterministic tie-breaker while absolute error remains the
    # primary (and required) ordering criterion.
    candidates.sort(key=lambda item: (item["match_quality"], item["name"].casefold()))
    return candidates[:limit]


def _build_parser() -> argparse.ArgumentParser:
    parser = argparse.ArgumentParser(
        description="Find local molecules close to a target RDKit property"
    )
    parser.add_argument("--query", required=True, help="Case-insensitive name substring")
    parser.add_argument(
        "--property",
        dest="property_name",
        required=True,
        choices=sorted(SUPPORTED_PROPERTIES),
        help="Property to target",
    )
    parser.add_argument("--target", required=True, type=float, help="Target value")
    parser.add_argument(
        "--tolerance", type=float, default=0.5, help="Maximum absolute difference"
    )
    parser.add_argument("--limit", type=int, default=10, help="Maximum results")
    return parser


def main() -> int:
    parser = _build_parser()
    args = parser.parse_args()
    try:
        results = find_candidates_for_property(
            property_name=args.property_name,
            target_value=args.target,
            query=args.query,
            tolerance=args.tolerance,
            limit=args.limit,
        )
    except (TypeError, ValueError, OSError) as exc:
        parser.error(str(exc))
    print(json.dumps(results, indent=2, sort_keys=False))
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
"}

{"path": "/app/gen_gates.py", "content": "#!/usr/bin/env python3

# Generate an ascending-index combinational network plus a small feedback state
# machine.  Bit vectors are little-endian lists of signal indices.

class Circuit:
    def __init__(self):
        self.lines = [None] * 32
        for i in range(32):
            self.lines[i] = f"out{i} = out{i}"

    def reserve(self, n):
        base = len(self.lines)
        self.lines.extend([None] * n)
        return list(range(base, base + n))

    def emit(self, rhs):
        i = len(self.lines)
        self.lines.append(f"out{i} = {rhs}")
        return i

    def const(self, x):
        return self.emit(str(int(bool(x))))

    def NOT(self, a):
        return self.emit(f"~out{a}")

    def AND(self, a, b):
        return self.emit(f"out{a} & out{b}")

    def OR(self, a, b):
        return self.emit(f"out{a} | out{b}")

    def XOR(self, a, b):
        return self.emit(f"out{a} ^ out{b}")

    def mux(self, sel, a, b):
        # a when sel=0, b when sel=1
        return self.XOR(a, self.AND(sel, self.XOR(a, b)))

    def patch_copy(self, dst, src):
        self.lines[dst] = f"out{dst} = out{src}"

c = Circuit()
ZERO = c.const(0)
ONE = c.const(1)

# State registers.  Their definitions are patched to copy the next-state
# signals, which have larger indices.  Zero initialization supplied by sim.c
# encodes k=0, F(k)=0, F(k-1)=0.
kreg = c.reserve(16)
preg = c.reserve(32)
qreg = c.reserve(32)

# Unsigned subtraction x-y. Returns (difference, borrow), where final borrow
# is exactly x<y. Inputs and result have the same width.
def sub(x, y):
    borrow = ZERO
    d = []
    for xb, yb in zip(x, y):
        t = c.XOR(xb, yb)
        d.append(c.XOR(t, borrow))
        # borrow' = (~x & y) | (borrow & ~(x^y))
        u = c.AND(c.NOT(xb), yb)
        v = c.AND(borrow, c.NOT(t))
        borrow = c.OR(u, v)
    return d, borrow

# Restoring radix-4 integer square root, processing input pairs MSB first.
root = [ZERO] * 16
rem = [ZERO] * 18
for turn in range(16):
    bitlo = 30 - 2 * turn
    shifted = [bitlo, bitlo + 1] + rem[:16]
    trial = [ONE, ZERO] + root
    diff, borrow = sub(shifted, trial)
    take = c.NOT(borrow)                 # shifted >= trial
    rem = [c.mux(take, shifted[i], diff[i]) for i in range(18)]
    root = [take] + root[:15]

# OR-reduction followed by NOT.
def is_zero(x):
    v = ZERO
    for b in x:
        v = c.OR(v, b)
    return c.NOT(v)

# Add two 32-bit words modulo 2^32, with a one-bit carry-in.
def add32(x, y, carry):
    out = []
    for xb, yb in zip(x, y):
        t = c.XOR(xb, yb)
        out.append(c.XOR(t, carry))
        carry = c.OR(c.AND(xb, yb), c.AND(carry, t))
    return out

# One conditional recurrence step. State invariant after k>0:
# p=F(k), q=F(k-1).  The carry-in at k=0 changes 0+0 into F(1)=1.
def fib_step(k, p, q):
    _, less = sub(k, root)               # active iff k < floor(sqrt(N))
    candidate = add32(p, q, is_zero(k))

    # Conditional increment k += active.
    carry = less
    nk = []
    for kb in k:
        nk.append(c.XOR(kb, carry))
        carry = c.AND(kb, carry)

    np = [c.mux(less, p[i], candidate[i]) for i in range(32)]
    nq = [c.mux(less, q[i], p[i]) for i in range(32)]
    return nk, np, nq

# Three recurrences per simulator step are enough for all 16-bit roots to
# finish within the fixed 32000-step run.
nk, np, nq = kreg, preg, qreg
for _ in range(3):
    nk, np, nq = fib_step(nk, np, nq)

for dst, src in zip(kreg, nk):
    c.patch_copy(dst, src)
for dst, src in zip(preg, np):
    c.patch_copy(dst, src)
for dst, src in zip(qreg, nq):
    c.patch_copy(dst, src)

# The simulator interprets the final 32 signals little-endian.
for src in preg:
    c.emit(f"out{src}")

assert all(line is not None for line in c.lines)
assert len(c.lines) < 32000
with open('/app/gates.txt', 'w', encoding='ascii') as f:
    f.write('\n'.join(c.lines) + '\n')
print(f"generated {len(c.lines)} gates")
"}

