{"path": "/app/generate_report.py", "content": "from collections import Counter
from pathlib import Path

log_path = Path("/app/log.stack")
output_path = Path("/app/output.txt")

lines = [line.decode("utf-8", errors="replace") for line in log_path.read_bytes().splitlines()]
trace_starts = [index for index, line in enumerate(lines) if line.strip().isdigit()]

call_sites = []
for trace_index, start in enumerate(trace_starts):
    end = trace_starts[trace_index + 1] if trace_index + 1 < len(trace_starts) else len(lines)
    frames = []
    for line in lines[start + 1 : end]:
        stripped = line.strip()
        if stripped.startswith("in "):
            frames.append(stripped[3:])
    if len(frames) >= 3:
        call_sites.append(tuple(frames[:3]))

counts = Counter(call_sites)
first_seen = {}
for index, call_site in enumerate(call_sites):
    first_seen.setdefault(call_site, index)
most_common = sorted(counts, key=lambda site: (-counts[site], first_seen[site]))[:10]

report = [
    f"Found {len(trace_starts)} stack traces",
    f"Number of unique call sites (based on top 3 frames): {len(counts)}",
    f"Total stack traces analyzed: {len(call_sites)}",
    "",
    "Most common call sites:",
    "",
]

for rank, call_site in enumerate(most_common, 1):
    report.append(f"{rank}. Count: {counts[call_site]}")
    for frame_number, frame in enumerate(call_site, 1):
        report.append(f"  Frame {frame_number}: {frame}")
    if rank != len(most_common):
        report.append("")

output_path.write_text("\n".join(report) + "\n", encoding="utf-8")
"}

