namespace sum_array_detail
{
template <std::size_t I, std::size_t N>
struct summer
{
    template <typename T>
    static constexpr T sum(const std::array<T, N> &arr, T value)
    {
        return summer<I + 1, N>::sum(arr, value + std::get<I>(arr));
    }
};

template <std::size_t N>
struct summer<N, N>
{
    template <typename T>
    static constexpr T sum(const std::array<T, N> &, T value)
    {
        return value;
    }
};
} // namespace sum_array_detail

template <typename T, std::size_t N>
constexpr T sum_array(const std::array<T, N> &arr)
{
    return sum_array_detail::summer<0, N>::sum(arr, T(0));
}
