"""
Test the exact example from the issue to verify it works.
"""
import caparg as ca
import elcaminoreal

COMMANDS = elcaminoreal.Commands()


# Define some dependencies
@COMMANDS.dependency()
def foo(_deps, _possible):
    return 10


@COMMANDS.dependency()
def bar(_deps, _possible):
    return 5


@COMMANDS.dependency()
def baz(_deps, _possible):
    return 3


# Example from the issue - dependency with regular=True
@COMMANDS.dependency(
        dependencies=['foo', 'bar'],
        possible_dependencies=['baz'],
        regular=True)
def thing(foo, bar, build_baz):
    val = foo()
    if val > 5:
        val -= build_baz()
    return val + bar()


# Make foo, bar, baz callable (they return values, not functions)
# Let's redefine them as functions that return values
@COMMANDS.dependency(name='foo')
def foo_func(_deps, _possible):
    def _foo():
        return 10
    return _foo


@COMMANDS.dependency(name='bar')
def bar_func(_deps, _possible):
    def _bar():
        return 5
    return _bar


@COMMANDS.dependency(name='baz')
def baz_func(_deps, _possible):
    def _baz():
        return 3
    return _baz


# Example from the issue - command with regular=True
@COMMANDS.command(
    dependencies=['thing'],
    parser=ca.command('',
                      ca.positional('lala', type=str)),
    regular=True)
def do_stuff(thing, lala):
    return str(thing) + lala


if __name__ == '__main__':
    # Test the dependency
    result = COMMANDS.mkgraph(['thing'])
    print(f"thing dependency result: {result['thing']}")
    # foo() returns 10, which is > 5, so val = 10 - 3 = 7
    # then val + bar() = 7 + 5 = 12
    assert result['thing'] == 12, f"Expected 12, got {result['thing']}"

    # Test the command
    result = COMMANDS.run(['do-stuff', 'hello'])
    print(f"do_stuff command result: {result}")
    # thing = 12, lala = 'hello', so result = '12hello'
    assert result == '12hello', f"Expected '12hello', got {result}"

    print("\n✓ All examples from the issue work correctly!")
"}

