def occupied(st):
    occ={}
    for i,(h,w) in enumerate(dims):
        p=st[i]; r,c=divmod(p,W)
        for dr in range(h):
            for dc in range(w): occ[(r+dr)*W+c]=i
    for j,p in enumerate(st[6:]): occ[p]=6+j
    return occ

def successors(st):
    occ=occupied(st)
    # normal pieces
    for i,(h,w) in enumerate(dims):
        p=st[i]; r,c=divmod(p,W)
        for dr,dc in ((-1,0),(1,0),(0,-1),(0,1)):
            nr,nc=r+dr,c+dc
            if nr<0 or nc<0 or nr+h>H or nc+w>W: continue
            good=True
            for rr in range(nr,nr+h):
                for cc in range(nc,nc+w):
                    q=rr*W+cc
                    if q in occ and occ[q]!=i: good=False
            if good:
                ns=list(st); ns[i]=nr*W+nc
                yield tuple(ns)
    # indistinguishable soldiers; sorting canonicalizes them
    sold=list(st[6:])
    soldset=set(sold)
    for k,p in enumerate(sold):
