from decimal import Decimal, ROUND_HALF_UP
from pathlib import Path

amounts = defaultdict(Decimal)
items = defaultdict(int)
tag_counts = defaultdict(int)
record_count = 0

files = sorted(glob.glob('/app/records_*.jsonl'))
if not files:
    raise SystemExit('No records_*.jsonl files found')

for filename in files:
    with open(filename, 'r', encoding='utf-8') as fh:
        for line_no, line in enumerate(fh, 1):
            if not line.strip():
                continue
            try:
                record = json.loads(line)
                user = record['user']
                amount = Decimal(str(record['amount']))
                item_count = record['items']
                tags = record['tags']
            except Exception as exc:
                raise ValueError(f'{filename}:{line_no}: invalid record: {exc}') from exc
            if not isinstance(user, str) or not isinstance(item_count, int) or isinstance(item_count, bool) or not isinstance(tags, list):
                raise TypeError(f'{filename}:{line_no}: unexpected field type')
            amounts[user] += amount
            items[user] += item_count
            for tag in tags:
                if not isinstance(tag, str):
                    raise TypeError(f'{filename}:{line_no}: tag is not a string')
                tag_counts[tag] += 1
            record_count += 1

top_users = sorted(amounts, key=lambda user: (-amounts[user], user))[:5]
top_tags = sorted(tag_counts, key=lambda tag: (-tag_counts[tag], tag))[:5]

