from collections import Counter

suits='DBC'
tiles=[f'{n}{s}' for s in suits for n in range(1,10)] + ['East','South','West','North','Red','Green','White']
orphans={'1D','9D','1B','9B','1C','9C','East','South','West','North','Red','Green','White'}

def seven(hand):
