def thirteen(hand):
    c=Counter(hand)
    return len(hand)==14 and set(c)==orphans and sorted(c.values()) == [1]*12+[2]

def standard(hand):
    c=Counter(hand)
    def melds(c, remaining):
        if remaining == 0:
            return not any(c.values())
        t=next((x for x in tiles if c[x]), None)
        if t is None:
            return False
        if c[t] >= 3:
            c[t]-=3
            if melds(c,remaining-3):
                c[t]+=3
                return True
            c[t]+=3
        if len(t)==2 and t[0].isdigit():
