{"path": "/app/serial.c", "content": "#include "particle.h"

int main(int argc, char **argv)
{
    options_t opt;
    if (!parse_options(argc, argv, &opt, 0, "/app/serial.txt",
                       "/app/serial_summary.txt")) return EXIT_FAILURE;

    particle_t *p = (particle_t *)malloc((size_t)opt.n * sizeof(*p));
    if (!p) { fprintf(stderr, "out of memory\n"); return EXIT_FAILURE; }
    double cutoff;
    double size = initialize_particles(p, opt.n, &cutoff);
    bins_t bins;
    bins_create(&bins, opt.n, size, cutoff);
    stats_t stats = {HUGE_VAL, 0.0, 0};

    double start = wall_time();
    for (int step = 0; step < NSTEPS; ++step) {
        bins_rebuild(&bins, p, opt.n);
        for (int i = 0; i < opt.n; ++i) force_on(i, p, &bins, cutoff, &stats);
        for (int i = 0; i < opt.n; ++i) move_particle(&p[i], size);
    }
    double elapsed = wall_time() - start;

    double absmin, absavg;
    final_metrics(&stats, &absmin, &absavg);
    printf("n = %d, simulation time = %.6f seconds\n", opt.n, elapsed);
    printf("absmin = %.6f\nabsavg = %.6f\n", absmin, absavg);

    int ok = write_positions(opt.output, p, opt.n, size);
    FILE *summary = fopen(opt.summary, "w");
    if (!summary) { perror(opt.summary); ok = 0; }
    else {
        fprintf(summary, "%d %.9f\n", opt.n, elapsed);
        if (fclose(summary)) { perror(opt.summary); ok = 0; }
    }
    bins_destroy(&bins);
    free(p);
    return ok ? EXIT_SUCCESS : EXIT_FAILURE;
}
"}

