from __future__ import annotations

import hashlib
import json
import os
from concurrent.futures import ProcessPoolExecutor
from pathlib import Path

from compute_seq import BUFSIZE, ITERATIONS

DATA_DIR = Path("/app/data/blobs")
SALT_FILE = Path("/app/input/salt.txt")
OUT = Path("/app/output/results.json")


def _pbkdf2_file(path: Path, relative_path: str, salt: bytes) -> dict[str, str]:
    """Read and derive one file's key inside a worker process."""
    chunks: list[bytes] = []
    with path.open("rb") as source:
        for chunk in iter(lambda: source.read(BUFSIZE), b""):
            chunks.append(chunk)

    derived = hashlib.pbkdf2_hmac(
        "sha256", b"".join(chunks), salt, ITERATIONS, dklen=32
    )
    return {"path": relative_path, "pbkdf2": derived.hex()}


def _available_cpus() -> int:
    """Respect a CPU affinity restriction when the platform exposes one."""
    try:
        return max(1, len(os.sched_getaffinity(0)))
    except AttributeError:
        return max(1, os.cpu_count() or 1)


def main() -> None:
    salt_hex = SALT_FILE.read_text().strip()
    salt = bytes.fromhex(salt_hex)

    paths = [path for path in DATA_DIR.rglob("*") if path.is_file()]
    tasks = [(path, str(path.relative_to(DATA_DIR)), salt) for path in paths]

    rows: list[dict[str, str]] = []
    if tasks:
        worker_count = min(len(tasks), _available_cpus())
        with ProcessPoolExecutor(max_workers=worker_count) as executor:
            # One independently submitted process task per file is intentional.
            futures = [executor.submit(_pbkdf2_file, *task) for task in tasks]
            rows = [future.result() for future in futures]

    rows.sort(key=lambda row: row["path"])
    result = {
        "salt_hex": salt_hex,
        "iterations": ITERATIONS,
        "files": rows,
    }
    OUT.parent.mkdir(parents=True, exist_ok=True)
    OUT.write_text(json.dumps(result))


if __name__ == "__main__":
    main()
"}

