#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define BASE 1000000000U

typedef struct {
    unsigned int *d;
    size_t n, cap;
} Big;

static void init(Big *x, unsigned int value) {
    x->cap = 1;
    x->n = 1;
    x->d = malloc(sizeof(*x->d));
    if (!x->d) exit(1);
    x->d[0] = value;
}

static void reserve(Big *x, size_t cap) {
    if (cap > x->cap) {
        unsigned int *p = realloc(x->d, cap * sizeof(*p));
        if (!p) exit(1);
        x->d = p;
        x->cap = cap;
    }
}

static void add_into(Big *out, const Big *a, const Big *b) {
    size_t n = a->n > b->n ? a->n : b->n;
    reserve(out, n + 1);
    unsigned long long carry = 0;
    for (size_t i = 0; i < n; ++i) {
        unsigned long long sum = carry;
        if (i < a->n) sum += a->d[i];
        if (i < b->n) sum += b->d[i];
        out->d[i] = (unsigned int)(sum % BASE);
        carry = sum / BASE;
    }
    if (carry) out->d[n++] = (unsigned int)carry;
    out->n = n;
}

static void print_big(const Big *x) {
    printf("%u", x->d[x->n - 1]);
    for (size_t i = x->n - 1; i-- > 0;)
        printf("%09u", x->d[i]);
    putchar('\n');
}

int main(int argc, char **argv) {
    if (argc != 2) return 1;
    char *end;
    unsigned long long k = strtoull(argv[1], &end, 10);
    if (*argv[1] == '-' || *end != '\0') return 1;

    Big a, b, c;
    init(&a, 0);
    init(&b, 1);
    init(&c, 0);
    for (unsigned long long i = 0; i < k; ++i) {
        add_into(&c, &a, &b);
        Big tmp = a;
        a = b;
        b = c;
        c = tmp;
    }
    print_big(&a);
    free(a.d);
    free(b.d);
    free(c.d);
    return 0;
}
