{"path": "/app/portfolio_optimized.c", "content": "/*
 * High-performance portfolio calculations using the NumPy C API.
 */

#define NPY_NO_DEPRECATED_API NPY_1_7_API_VERSION
#include <Python.h>
#include <numpy/arrayobject.h>
#include <math.h>

/*
 * The Python wrapper supplies C-contiguous float64 arrays.  Keeping the
 * validation here as well makes misuse of the extension module fail cleanly
 * instead of reading invalid memory.
 */
static int check_vector(PyArrayObject *array, const char *name) {
    if (PyArray_NDIM(array) != 1) {
        PyErr_Format(PyExc_ValueError, "%s must be a one-dimensional array", name);
        return 0;
    }
    if (PyArray_TYPE(array) != NPY_DOUBLE || !PyArray_ISCARRAY_RO(array)) {
        PyErr_Format(PyExc_TypeError,
                     "%s must be a C-contiguous float64 NumPy array", name);
        return 0;
    }
    return 1;
}

static PyObject *portfolio_risk_c(PyObject *self, PyObject *args) {
    PyArrayObject *weights_array;
    PyArrayObject *cov_array;
    npy_intp n;
    const double *weights;
    const double *cov;
    double risk_squared = 0.0;

    (void)self;
    if (!PyArg_ParseTuple(args, "O!O!", &PyArray_Type, &weights_array,
                          &PyArray_Type, &cov_array)) {
        return NULL;
    }

    if (!check_vector(weights_array, "weights")) {
        return NULL;
    }
    if (PyArray_NDIM(cov_array) != 2) {
        PyErr_SetString(PyExc_ValueError,
                        "cov_matrix must be a two-dimensional array");
        return NULL;
    }
    if (PyArray_TYPE(cov_array) != NPY_DOUBLE ||
        !PyArray_ISCARRAY_RO(cov_array)) {
        PyErr_SetString(PyExc_TypeError,
                        "cov_matrix must be a C-contiguous float64 NumPy array");
        return NULL;
    }

    n = PyArray_DIM(weights_array, 0);
    if (PyArray_DIM(cov_array, 0) != n || PyArray_DIM(cov_array, 1) != n) {
        PyErr_SetString(PyExc_ValueError,
                        "cov_matrix must have shape (len(weights), len(weights))");
        return NULL;
    }

    weights = (const double *)PyArray_DATA(weights_array);
    cov = (const double *)PyArray_DATA(cov_array);

    /* Match the baseline's operation order: each row dot product first,
       followed by the outer dot product.  No temporary vector is required. */
    Py_BEGIN_ALLOW_THREADS
    for (npy_intp i = 0; i < n; ++i) {
        const double *row = cov + i * n;
        double row_sum = 0.0;
        for (npy_intp j = 0; j < n; ++j) {
            row_sum += row[j] * weights[j];
        }
        risk_squared += weights[i] * row_sum;
    }
    Py_END_ALLOW_THREADS

    return PyFloat_FromDouble(sqrt(risk_squared));
}

static PyObject *portfolio_return_c(PyObject *self, PyObject *args) {
    PyArrayObject *weights_array;
    PyArrayObject *returns_array;
