"""Reconstruct an original directory in-place from compress.py shards."""

from __future__ import annotations

import argparse
import os
import shutil
import sys
import tarfile
from pathlib import Path, PurePosixPath

CONTAINER = "resharded-data"


class ShardReader:
    """Present sorted shard files as one sequential readable stream."""

    def __init__(self, root: Path) -> None:
        self.paths = sorted(path for path in root.rglob("*.bin") if path.is_file())
        if not self.paths:
            raise ValueError("no archive shards found")
        self.position = 0
        self.current = None

    def _advance(self) -> bool:
        if self.current is not None:
            self.current.close()
        if self.position >= len(self.paths):
            self.current = None
            return False
        self.current = self.paths[self.position].open("rb")
        self.position += 1
        return True

    def read(self, size: int = -1) -> bytes:
        if size == 0:
            return b""
        chunks: list[bytes] = []
        remaining = size
        while size < 0 or remaining > 0:
            if self.current is None and not self._advance():
                break
            assert self.current is not None
            chunk = self.current.read(-1 if size < 0 else remaining)
            if chunk:
                chunks.append(chunk)
                if size >= 0:
                    remaining -= len(chunk)
            else:
                self.current.close()
                self.current = None
        return b"".join(chunks)

    def close(self) -> None:
        if self.current is not None:
            self.current.close()
            self.current = None

    def readable(self) -> bool:
        return True


def parse_args() -> argparse.Namespace:
    parser = argparse.ArgumentParser(description="Restore a resharded directory in-place.")
    parser.add_argument("resharded_dir", type=Path)
    return parser.parse_args()


def safe_member(member: tarfile.TarInfo) -> None:
    """Reject archive paths or link targets that can escape the extraction root."""
    path = PurePosixPath(member.name)
    if path.is_absolute() or ".." in path.parts:
        raise ValueError(f"unsafe archive path: {member.name!r}")
    if member.issym() or member.islnk():
        target = PurePosixPath(member.linkname)
        if target.is_absolute():
            raise ValueError(f"unsafe absolute link target: {member.linkname!r}")
        # Resolve a relative link lexically from its parent.
        depth = 0
        for part in (path.parent / target).parts:
            if part in ("", "."):
                continue
            if part == "..":
                depth -= 1
                if depth < 0:
                    raise ValueError(f"unsafe link target: {member.linkname!r}")
            else:
                depth += 1


def main() -> int:
    args = parse_args()
    root = args.resharded_dir.absolute()
    container = root / CONTAINER
    try:
        if not root.is_dir():
            raise ValueError(f"resharded path is not a directory: {args.resharded_dir}")
        if root.is_symlink() or container.is_symlink() or not container.is_dir():
            raise ValueError("not a valid resharded directory")
        # The compressor requires an empty destination and creates only this container.
        # Refuse ambiguous trees rather than deleting unrelated user data.
        if any(path.name != CONTAINER for path in root.iterdir()):
            raise ValueError("resharded directory contains unexpected top-level entries")

        reader = ShardReader(container)
        try:
            with tarfile.open(fileobj=reader, mode="r|gz") as archive:
                for member in archive:
                    safe_member(member)
                    archive.extract(member, path=root, set_attrs=True)
        finally:
            reader.close()

        # Remove archive data only after successful extraction.
        shutil.rmtree(container)
        return 0
    except (OSError, ValueError, tarfile.TarError) as exc:
        print(f"decompress.py: error: {exc}", file=sys.stderr)
        return 1


if __name__ == "__main__":
    raise SystemExit(main())
"}

