{"path": "/app/scraper.py", "content": "#!/usr/bin/env python3
"""Scrape book data from the local bookstore and create CSV/report outputs."""

import re
from pathlib import Path

import pandas as pd
import requests
from bs4 import BeautifulSoup

URL = "http://server:8000"
CSV_PATH = Path("/app/books.csv")
REPORT_PATH = Path("/app/report.txt")
COLUMNS = ["title", "author", "year", "rating", "price"]


def element_text(book, selector: str) -> str:
    """Return normalized text for a required child element."""
    element = book.select_one(selector)
    if element is None:
        raise ValueError(f"Book entry is missing required element {selector!r}")
    return element.get_text(" ", strip=True)


def extract_number(text: str, field: str, number_type=float):
    """Extract the first integer/decimal value from a labeled field."""
    match = re.search(r"-?\d+(?:\.\d+)?", text.replace(",", ""))
    if not match:
        raise ValueError(f"Could not parse {field} from {text!r}")
    return number_type(match.group())


def scrape_books(url: str = URL) -> pd.DataFrame:
    """Download *url* and return its book listings as a DataFrame."""
    response = requests.get(url, timeout=30)
    response.raise_for_status()
    soup = BeautifulSoup(response.text, "html.parser")

    records = []
    for book in soup.select("div.book"):
        author = element_text(book, ".book-author")
        # The display text uses "by Author"; remove only that leading label.
        author = re.sub(r"^by\s+", "", author, flags=re.IGNORECASE)

        records.append(
            {
                "title": element_text(book, ".book-title"),
                "author": author,
                "year": extract_number(
                    element_text(book, ".book-year"), "year", int
                ),
                "rating": extract_number(
                    element_text(book, ".book-rating"), "rating", float
                ),
                "price": extract_number(
                    element_text(book, ".book-price"), "price", float
                ),
            }
        )

    return pd.DataFrame(records, columns=COLUMNS)


def create_report(books: pd.DataFrame) -> str:
    """Build the requested plain-text summary report."""
    total = len(books)
    if books.empty:
        return (
            "Book Scraping Summary\n"
            "=====================\n"
            "Total number of books scraped: 0\n"
            "Average book price: N/A\n"
            "Highest rated book: N/A\n"
        )

    highest = books.loc[books["rating"].idxmax()]
    return (
        "Book Scraping Summary\n"
        "=====================\n"
        f"Total number of books scraped: {total}\n"
        f"Average book price: ${books['price'].mean():.2f}\n"
        f"Highest rated book: {highest['title']} "
        f"(Rating: {highest['rating']:.1f}/5)\n"
    )


def main() -> None:
    books = scrape_books()
    books.to_csv(CSV_PATH, index=False, columns=COLUMNS)
    REPORT_PATH.write_text(create_report(books), encoding="utf-8")
    print(f"Scraped {len(books)} books to {CSV_PATH}")
    print(f"Saved summary report to {REPORT_PATH}")


if __name__ == "__main__":
    main()
"}

{"path": "/app/app.py", "content": "import os
from typing import Any

import requests
from flask import Flask, jsonify, request
from werkzeug.exceptions import HTTPException

app = Flask(__name__)

NETWORK = os.getenv("SOLANA_NETWORK", "devnet")
RPC_URLS = {
    "devnet": "https://api.devnet.solana.com",
    "testnet": "https://api.testnet.solana.com",
    "mainnet-beta": "https://api.mainnet-beta.solana.com",
}
RPC_URL = os.getenv("SOLANA_RPC_URL", RPC_URLS.get(NETWORK, RPC_URLS["devnet"]))
TIMEOUT = float(os.getenv("SOLANA_RPC_TIMEOUT", "20"))


class APIError(Exception):
    def __init__(self, message: str, status_code: int = 502):
        super().__init__(message)
        self.message = message
        self.status_code = status_code


def rpc(method: str, params: list[Any] | None = None) -> Any:
    payload = {"jsonrpc": "2.0", "id": 1, "method": method, "params": params or []}
    try:
        response = requests.post(RPC_URL, json=payload, timeout=TIMEOUT)
        response.raise_for_status()
        body = response.json()
    except requests.Timeout as exc:
        raise APIError("Solana RPC request timed out", 504) from exc
    except requests.RequestException as exc:
        raise APIError(f"Solana RPC request failed: {exc}", 502) from exc
    except ValueError as exc:
        raise APIError("Solana RPC returned invalid JSON", 502) from exc

    if body.get("error"):
        error = body["error"]
        message = error.get("message", str(error)) if isinstance(error, dict) else str(error)
        raise APIError(message, 502)
    return body.get("result")


def account_summary(value: dict[str, Any]) -> dict[str, Any]:
    return {
        "executable": value.get("executable", False),
        "lamports": value.get("lamports", 0),
        "owner": value.get("owner"),
        "rent_epoch": value.get("rentEpoch", 0),
    }


@app.errorhandler(APIError)
def handle_api_error(error: APIError):
    return jsonify(error=error.message), error.status_code


@app.errorhandler(HTTPException)
def handle_http_error(error: HTTPException):
    return jsonify(error=error.description), error.code


@app.errorhandler(Exception)
def handle_unexpected_error(error: Exception):
    app.logger.exception("Unhandled error")
    return jsonify(error=str(error) or "Internal server error"), 500


@app.get("/status")
def status():
    try:
        slot = rpc("getSlot", [{"commitment": "confirmed"}])
        nodes = rpc("getClusterNodes")
        version_info = rpc("getVersion")
        version = version_info.get("solana-core") if isinstance(version_info, dict) else str(version_info)
        return jsonify(
            status="online",
            network=NETWORK,
            current_slot=slot,
            node_count=len(nodes or []),
            version=version,
        )
    except APIError as exc:
        # Status is the one endpoint where RPC unavailability is itself useful data.
        return jsonify(
            status="offline",
            network=NETWORK,
            current_slot=None,
            node_count=0,
            version=None,
            error=exc.message,
        ), exc.status_code


@app.get("/block/<int:slot_number>")
def block(slot_number: int):
    result = rpc(
        "getBlock",
        [slot_number, {"commitment": "confirmed", "transactionDetails": "none", "rewards": False}],
    )
    if result is None:
        raise APIError("Block not found", 404)
    return jsonify(
        blockhash=result.get("blockhash"),
        parent_slot=result.get("parentSlot"),
        previous_blockhash=result.get("previousBlockhash"),
        block_height=result.get("blockHeight"),
        block_time=result.get("blockTime"),
    )


def parsed_instruction_transfers(transaction: dict[str, Any]) -> list[dict[str, Any]]:
    transfers: list[dict[str, Any]] = []
    message = transaction.get("transaction", {}).get("message", {})
    meta = transaction.get("meta") or {}
    instructions = list(message.get("instructions") or [])
    for group in meta.get("innerInstructions") or []:
        instructions.extend(group.get("instructions") or [])

    for instruction in instructions:
        parsed = instruction.get("parsed") if isinstance(instruction, dict) else None
        if not isinstance(parsed, dict) or parsed.get("type") not in ("transfer", "transferChecked"):
            continue
        info = parsed.get("info") or {}
        token_amount = info.get("tokenAmount") or {}
        mint = info.get("mint")
        amount = token_amount.get("uiAmountString")
        if amount is None:
            amount = info.get("amount")
        # Plain SPL transfer instructions do not carry the mint. Resolve it from
        # transaction token-balance metadata by token-account address when possible.
        source = info.get("source") or info.get("authority")
        if mint is None and source:
            keys = message.get("accountKeys") or []
            key_strings = [key.get("pubkey") if isinstance(key, dict) else key for key in keys]
            for balance in (meta.get("preTokenBalances") or []) + (meta.get("postTokenBalances") or []):
                index = balance.get("accountIndex")
                if isinstance(index, int) and index < len(key_strings) and key_strings[index] == source:
                    mint = balance.get("mint")
                    break
        if source and mint is not None and amount is not None:
            transfers.append({"account": source, "mint": mint, "amount": amount})
    return transfers


def balance_delta_transfers(transaction: dict[str, Any]) -> list[dict[str, Any]]:
    """Return changed token accounts when parsed transfer instructions are unavailable."""
    meta = transaction.get("meta") or {}
    message = transaction.get("transaction", {}).get("message", {})
    keys = message.get("accountKeys") or []
    key_strings = [key.get("pubkey") if isinstance(key, dict) else key for key in keys]

    def balances(items: list[dict[str, Any]]) -> dict[tuple[int, str], int]:
        output: dict[tuple[int, str], int] = {}
        for item in items:
            raw = (item.get("uiTokenAmount") or {}).get("amount")
            if raw is not None:
                output[(item.get("accountIndex"), item.get("mint"))] = int(raw)
        return output

    pre = balances(meta.get("preTokenBalances") or [])
    post = balances(meta.get("postTokenBalances") or [])
    transfers = []
    for key in sorted(set(pre) | set(post), key=lambda item: (item[0], item[1])):
        delta = post.get(key, 0) - pre.get(key, 0)
        index, mint = key
        if delta and isinstance(index, int) and index < len(key_strings):
            transfers.append({"account": key_strings[index], "mint": mint, "amount": str(delta)})
    return transfers


@app.get("/transaction/<signature>")
def transaction(signature: str):
    result = rpc(
        "getTransaction",
        [signature, {"commitment": "confirmed", "encoding": "jsonParsed", "maxSupportedTransactionVersion": 0}],
    )
    if result is None:
        raise APIError("Transaction not found", 404)
    meta = result.get("meta") or {}
    transfers = parsed_instruction_transfers(result)
    if not transfers:
        transfers = balance_delta_transfers(result)
    return jsonify(
        signature=signature,
        slot=result.get("slot"),
        block_time=result.get("blockTime"),
        success=meta.get("err") is None,
        fee=meta.get("fee"),
        token_transfers=transfers,
    )


@app.get("/account/<address>")
def account(address: str):
    result = rpc("getAccountInfo", [address, {"encoding": "base64", "commitment": "confirmed"}])
    value = result.get("value") if isinstance(result, dict) else None
    if value is None:
        raise APIError("Account not found", 404)
    return jsonify(address=address, **account_summary(value))


@app.get("/program/<program_id>/accounts")
def program_accounts(program_id: str):
    try:
        offset = int(request.args.get("offset", "0"))
        limit = int(request.args.get("limit", "10"))
    except ValueError as exc:
        raise APIError("offset and limit must be integers", 400) from exc
    if offset < 0:
        raise APIError("offset must be non-negative", 400)
    if limit < 1:
        raise APIError("limit must be at least 1", 400)
    if limit > 1000:
        raise APIError("limit must not exceed 1000", 400)

    result = rpc("getProgramAccounts", [program_id, {"encoding": "base64", "commitment": "confirmed"}])
    all_accounts = result or []
    page = all_accounts[offset : offset + limit]
    accounts = [
        {"pubkey": item.get("pubkey"), "account": account_summary(item.get("account") or {})}
        for item in page
    ]
    return jsonify(
        program_id=program_id,
        total_accounts=len(all_accounts),
        limit=limit,
        offset=offset,
        accounts=accounts,
    )


if __name__ == "__main__":
    app.run(host="0.0.0.0", port=5000)
"}

