from starlette.applications import Starlette
from starlette.responses import JSONResponse
from starlette.routing import Route
from starlette.testclient import TestClient
from prometheus_client import REGISTRY

from starlette_exporter import PrometheusMiddleware, handle_openmetrics


def homepage(request):
    return JSONResponse({"status": "ok"})


def metrics(request):
    return handle_openmetrics(request)


# Unregister all collectors
collectors = list(REGISTRY._collector_to_names.keys())
for collector in collectors:
    REGISTRY.unregister(collector)

PrometheusMiddleware._metrics = {}


# Test 1: Exemplar callback with request parameter
def exemplar_with_request(request):
    """Exemplar callback that accepts request"""
    trace_id = request.headers.get("X-Trace-Id", "unknown")
    return {"trace_id": trace_id}


app1 = Starlette(
    routes=[
        Route("/", homepage),
        Route("/metrics", metrics),
    ]
)
app1.add_middleware(
    PrometheusMiddleware,
    exemplars=exemplar_with_request,
    labels={"test": "with_request"}
)

client1 = TestClient(app1)
response1 = client1.get("/", headers={"X-Trace-Id": "trace-123"})
assert response1.status_code == 200

metrics_output1 = client1.get("/metrics").content.decode()
print("Test 1 - Exemplar with request parameter:")
print("=" * 60)
for line in metrics_output1.split("\n"):
    if "test=\"with_request\"" in line and "trace_id" in line:
        print(line)
        assert 'trace_id="trace-123"' in line, f"Expected trace_id='trace-123' in {line}"
        print("✓ Found expected trace_id in exemplar")
        break
else:
    print("ERROR: Could not find exemplar with trace_id")
    print(metrics_output1)
    exit(1)


# Test 2: Backward compatibility - Exemplar callback without request parameter
collectors = list(REGISTRY._collector_to_names.keys())
for collector in collectors:
    REGISTRY.unregister(collector)
PrometheusMiddleware._metrics = {}


def exemplar_without_request():
    """Exemplar callback without request parameter (backward compatibility)"""
    return {"trace_id": "static-trace"}


app2 = Starlette(
    routes=[
        Route("/", homepage),
        Route("/metrics", metrics),
    ]
)
app2.add_middleware(
    PrometheusMiddleware,
    exemplars=exemplar_without_request,
    labels={"test": "without_request"}
)

client2 = TestClient(app2)
response2 = client2.get("/")
assert response2.status_code == 200

metrics_output2 = client2.get("/metrics").content.decode()
print("\nTest 2 - Exemplar without request parameter (backward compatibility):")
print("=" * 60)
for line in metrics_output2.split("\n"):
    if "test=\"without_request\"" in line and "trace_id" in line:
        print(line)
        assert 'trace_id="static-trace"' in line, f"Expected trace_id='static-trace' in {line}"
        print("✓ Found expected static trace_id in exemplar")
        break
else:
    print("ERROR: Could not find exemplar with static trace_id")
    print(metrics_output2)
    exit(1)

print("\n" + "=" * 60)
print("✓ All tests passed!")
print("=" * 60)
"}

