{"path": "/app/count_corners.cpp", "content": "#include <array>
#include <cmath>
#include <cstdint>
#include <fstream>
#include <iostream>
#include <sstream>
#include <string>
#include <vector>

using Mat = std::array<std::array<double,40>,6>;

static std::vector<double> read_csv(const std::string& path) {
    std::ifstream f(path);
    if (!f) throw std::runtime_error("cannot open " + path);
    std::vector<double> v;
    std::string line, cell;
    while (std::getline(f,line)) {
        std::stringstream ss(line);
        while (std::getline(ss,cell,',')) if (!cell.empty()) v.push_back(std::stod(cell));
    }
    return v;
}

// Pivoted Gaussian elimination. Random input is nondegenerate almost surely.
// Borderline sign decisions are repeated in long double.
static int feasible_double(const Mat& A, const std::array<double,6>& b,
                           const std::array<int,6>& c) {
    double m[6][7];
    double scale = 0;
    for(int i=0;i<6;i++) {
        for(int j=0;j<6;j++) { m[i][j]=A[i][c[j]]; scale=std::max(scale,std::abs(m[i][j])); }
        m[i][6]=b[i]; scale=std::max(scale,std::abs(m[i][6]));
    }
    double minpivot=1e300;
    for(int k=0;k<6;k++) {
        int p=k;
        for(int i=k+1;i<6;i++) if(std::abs(m[i][k])>std::abs(m[p][k])) p=i;
        minpivot=std::min(minpivot,std::abs(m[p][k]));
        if(p!=k) for(int j=k;j<7;j++) std::swap(m[p][j],m[k][j]);
        if(m[k][k]==0) return 2;
        for(int i=k+1;i<6;i++) {
            double q=m[i][k]/m[k][k];
            for(int j=k+1;j<7;j++) m[i][j]-=q*m[k][j];
        }
    }
    double x[6], xmin=1e300, xmax=0;
    for(int i=5;i>=0;i--) {
        double z=m[i][6];
        for(int j=i+1;j<6;j++) z-=m[i][j]*x[j];
        x[i]=z/m[i][i]; xmin=std::min(xmin,x[i]); xmax=std::max(xmax,std::abs(x[i]));
    }
    // Retry bases with tiny pivots or components near zero relative to solution size.
    if(minpivot < 1e-10*scale || std::abs(xmin) < 1e-10*std::max(1.0,xmax)) return 2;
    return xmin>=0 ? 1 : 0;
}

static bool feasible_long(const Mat& A, const std::array<double,6>& b,
                          const std::array<int,6>& c) {
    long double m[6][7];
    for(int i=0;i<6;i++) { for(int j=0;j<6;j++) m[i][j]=A[i][c[j]]; m[i][6]=b[i]; }
    for(int k=0;k<6;k++) {
        int p=k;
        for(int i=k+1;i<6;i++) if(fabsl(m[i][k])>fabsl(m[p][k])) p=i;
        if(p!=k) for(int j=k;j<7;j++) std::swap(m[p][j],m[k][j]);
        if(m[k][k]==0) return false;
        for(int i=k+1;i<6;i++) {
            long double q=m[i][k]/m[k][k];
            for(int j=k+1;j<7;j++) m[i][j]-=q*m[k][j];
        }
    }
    long double x[6];
    for(int i=5;i>=0;i--) {
        long double z=m[i][6];
        for(int j=i+1;j<6;j++) z-=m[i][j]*x[j];
        x[i]=z/m[i][i];
        if(x[i]<0) return false;
    }
    return true;
}

int main() {
    std::ofstream out("/app/corner_counts.txt");
    for(int inst=0;inst<3;inst++) {
        auto av=read_csv("/app/A_"+std::to_string(inst)+".csv");
        auto bv=read_csv("/app/b_"+std::to_string(inst)+".csv");
        if(av.size()!=240 || bv.size()!=6) throw std::runtime_error("bad dimensions");
        Mat A{}; std::array<double,6> b{};
        for(int i=0;i<6;i++) { for(int j=0;j<40;j++) A[i][j]=av[i*40+j]; b[i]=bv[i]; }
        std::uint64_t count=0, retry=0, total=0;
        std::array<int,6> c;
        for(c[0]=0;c[0]<35;c[0]++)
        for(c[1]=c[0]+1;c[1]<36;c[1]++)
        for(c[2]=c[1]+1;c[2]<37;c[2]++)
        for(c[3]=c[2]+1;c[3]<38;c[3]++)
        for(c[4]=c[3]+1;c[4]<39;c[4]++)
        for(c[5]=c[4]+1;c[5]<40;c[5]++) {
            int r=feasible_double(A,b,c); total++;
            if(r==1) count++;
            else if(r==2) { retry++; if(feasible_long(A,b,c)) count++; }
        }
        std::cerr << inst << ": " << count << " / " << total << " (" << retry << " precision retries)\n";
        out << count << '\n'; out.flush();
    }
}
"}

